import java.util.*;

public class RestPaging {
    public static void main(String[] a) {
        Scanner s = new Scanner(System.in);
        int offset = Math.max(0, s.nextInt()), limit = Math.max(1, Math.min(5, s.nextInt()));
        List<Integer> all = new ArrayList<>();
        for (int i = 1; i <= 10; i++) all.add(i);
        int from = Math.min(offset, all.size()), to = Math.min(from + limit, all.size());
        List<Integer> page = all.subList(from, to);
        int next = to < all.size() ? to : - 1;
        System.out.println("items=" + page + " nextOffset=" + next);
    }
}

